#include <stdlib.h>
static long long sortCount(long long*a,long long*t,int l,int r,long long lo,long long hi){if(r-l<=1)return 0;int m=(l+r)/2;long long c=sortCount(a,t,l,m,lo,hi)+sortCount(a,t,m,r,lo,hi);int p=m,q=m;for(int i=l;i<m;i++){while(p<r&&a[p]-a[i]<lo)p++;while(q<r&&a[q]-a[i]<=hi)q++;c+=q-p;}int i=l,j=m,k=l;while(i<m||j<r)t[k++]=(j==r||(i<m&&a[i]<=a[j]))?a[i++]:a[j++];for(i=l;i<r;i++)a[i]=t[i];return c;}int countRangeSum(int*nums,int n,int lower,int upper){long long*a=malloc((n+1)*sizeof(long long)),*t=malloc((n+1)*sizeof(long long));a[0]=0;for(int i=0;i<n;i++)a[i+1]=a[i]+nums[i];long long c=sortCount(a,t,0,n+1,lower,upper);free(a);free(t);return(int)c;}
